//! Wolfram exact-solve replay: A, A^T and A^H solves plus SVD.
//!
//! The fixture (`sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json`,
//! generated by `sonium-qa/wolfram/exact_linear_algebra.wls`) carries exact
//! systems with known solutions and singular values, per
//! audit-sonium-solvers-direct-20260921 (arbitrary-precision LinearSolve and
//! SVD on exact small matrices; certify A^T/A^H solves and backward error).
//! The matrix-function fixture
//! (`sonium-qa/wolfram/goldens/matrix-functions-v1.json`, generated by
//! `sonium-qa/wolfram/matrix_functions.wls`) carries MatrixExp and wide-SVD
//! references for the dense matrix-function APIs.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_solvers_core::dense::DenseMatrix;
use sonium_solvers_direct::{
    dense_svd, expm, lu_solve, lu_solve_conj_transpose, lu_solve_transpose,
};

const FIXTURE: &str =
    include_str!("../../../../../crates/sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json");
const MATRIX_FUNCTIONS: &str =
    include_str!("../../../../../crates/sonium-qa/wolfram/goldens/matrix-functions-v1.json");

#[derive(Debug, Deserialize)]
struct ComplexScalar {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize)]
struct RealSystem {
    a: Vec<Vec<String>>,
    x_exact: Vec<String>,
    b: Vec<String>,
    #[serde(default)]
    atx: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct ComplexSystem {
    a: Vec<Vec<ComplexScalar>>,
    v: Vec<ComplexScalar>,
    hermitian_v: Vec<ComplexScalar>,
}

#[derive(Debug, Deserialize)]
struct SvdCase {
    a: Vec<Vec<String>>,
    singular_values: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    nonsym_3x3: RealSystem,
    hilbert_4x4: RealSystem,
    hermitian_3x3: ComplexSystem,
    svd_3x2: SvdCase,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_complex(value: &ComplexScalar) -> Complex64 {
    Complex64::new(parse(&value.re), parse(&value.im))
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("valid exact linear-algebra fixture");
    assert_eq!(fixture.schema, "sonium-qa.exact-linear-algebra.v1");
    fixture
}

fn dense_real(rows: &[Vec<String>]) -> DenseMatrix<f64> {
    let flat: Vec<f64> = rows
        .iter()
        .flat_map(|row| row.iter().map(|value| parse(value)))
        .collect();
    DenseMatrix::from_row_major_vec(rows.len(), rows[0].len(), flat)
}

fn rel_error(x: &[f64], exact: &[f64]) -> f64 {
    let (mut num, mut den) = (0.0, 0.0);
    for (a, b) in x.iter().zip(exact.iter()) {
        num += (a - b) * (a - b);
        den += b * b;
    }
    num.sqrt() / den.sqrt()
}

#[test]
fn lu_solve_matches_wolfram_solution() {
    let fixture = parse_fixture();
    for (label, system) in [
        ("nonsym", &fixture.nonsym_3x3),
        ("hilbert", &fixture.hilbert_4x4),
    ] {
        let matrix = dense_real(&system.a);
        let b: Vec<f64> = system.b.iter().map(|value| parse(value)).collect();
        let x_exact: Vec<f64> = system.x_exact.iter().map(|value| parse(value)).collect();
        let x = lu_solve(&matrix, &b).expect("lu_solve failed");
        assert!(
            rel_error(&x, &x_exact) <= 1e-12,
            "{label}: solution error vs wolfram x"
        );
        // Backward error against the original matrix.
        let residual = matrix.matvec(&x);
        let mut backward = 0.0;
        let mut scale = 0.0;
        for ((r, bi), xi) in residual.iter().zip(b.iter()).zip(x.iter()) {
            backward += (r - bi) * (r - bi);
            scale += bi * bi + xi * xi;
        }
        assert!(
            (backward.sqrt()) <= 1e-13 * scale.sqrt().max(1.0),
            "{label}: backward error"
        );
    }
}

#[test]
fn lu_transpose_solve_matches_wolfram() {
    // A^T z = atx with the independent Wolfram transpose reference: the
    // solution must recover the fixture's y = [1, 0, -1].
    let fixture = parse_fixture();
    let matrix = dense_real(&fixture.nonsym_3x3.a);
    let atx: Vec<f64> = fixture
        .nonsym_3x3
        .atx
        .iter()
        .map(|value| parse(value))
        .collect();
    let z = lu_solve_transpose(&matrix, &atx).expect("lu transpose solve failed");
    assert!(
        rel_error(&z, &[1.0, 0.0, -1.0]) <= 1e-12,
        "A^T solve must recover wolfram y, got {z:?}"
    );
}

#[test]
fn lu_conj_transpose_solve_matches_wolfram() {
    // A^H z = hermitian_v with the independent Wolfram Hermitian reference:
    // the solution must recover the fixture's v.
    let fixture = parse_fixture();
    let case = &fixture.hermitian_3x3;
    let flat: Vec<Complex64> = case
        .a
        .iter()
        .flat_map(|row| row.iter().map(parse_complex))
        .collect();
    let matrix = DenseMatrix::from_row_major_vec(3, 3, flat);
    let rhs: Vec<Complex64> = case.hermitian_v.iter().map(parse_complex).collect();
    let expected: Vec<Complex64> = case.v.iter().map(parse_complex).collect();
    let z = lu_solve_conj_transpose(&matrix, &rhs).expect("lu conj-transpose solve failed");
    assert_eq!(z.len(), expected.len());
    for (index, (got, want)) in z.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).norm() <= 1e-12 * want.norm().max(1.0),
            "A^H solve[{index}]: {got:?} != {want:?}"
        );
    }
}

#[test]
fn dense_svd_matches_wolfram_singular_values() {
    let fixture = parse_fixture();
    let case = &fixture.svd_3x2;
    let matrix = dense_real(&case.a);
    let svd = dense_svd(&matrix).expect("dense_svd failed");
    let expected: Vec<f64> = case
        .singular_values
        .iter()
        .map(|value| parse(value))
        .collect();
    assert_eq!(svd.singular_values.len(), expected.len());
    for (index, (got, want)) in svd.singular_values.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).abs() <= 1e-12 * want.abs().max(1.0),
            "sigma[{index}]: {got:e} != {want:e}"
        );
    }
    assert!(
        svd.singular_values
            .windows(2)
            .all(|pair| pair[0] >= pair[1])
    );
    // Reconstruction A = U Σ V^T through the returned factors.
    let (m, n) = (matrix.nrows(), matrix.ncols());
    assert_eq!((m, n), (3, 2));
    let mut rebuilt = vec![0.0; m * n];
    for i in 0..m {
        for j in 0..n {
            let mut sum = 0.0;
            for k in 0..expected.len() {
                sum += svd.u.as_slice()[i * svd.u.ncols() + k]
                    * svd.singular_values[k]
                    * svd.v.as_slice()[j * svd.v.ncols() + k];
            }
            rebuilt[i * n + j] = sum;
        }
    }
    let original = matrix.as_slice();
    for (index, (got, want)) in rebuilt.iter().zip(original.iter()).enumerate() {
        assert!(
            (got - want).abs() <= 1e-12,
            "reconstruction[{index}]: {got:e} != {want:e}"
        );
    }
}

#[derive(Debug, Deserialize)]
struct ExpmCase {
    a: Vec<Vec<String>>,
    exp: Vec<Vec<String>>,
}

#[derive(Debug, Deserialize)]
struct WideSvdCase {
    a: Vec<Vec<String>>,
    singular_values: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct MatrixFunctionsFixture {
    schema: String,
    expm_nonsym_3x3: ExpmCase,
    expm_skew_2x2: ExpmCase,
    svd_wide_2x4: WideSvdCase,
}

fn parse_matrix_functions() -> MatrixFunctionsFixture {
    let fixture: MatrixFunctionsFixture =
        serde_json::from_str(MATRIX_FUNCTIONS).expect("valid matrix-functions fixture");
    assert_eq!(fixture.schema, "sonium-qa.matrix-functions.v1");
    fixture
}

fn check_expm(label: &str, case: &ExpmCase) {
    let matrix = dense_real(&case.a);
    let n = matrix.nrows();
    assert_eq!(matrix.ncols(), n);
    let result = expm(&matrix).expect("expm failed");
    for i in 0..n {
        for j in 0..n {
            let got = result[[i, j]];
            let want = parse(&case.exp[i][j]);
            assert!(
                (got - want).abs() <= 1e-12 * want.abs().max(1.0),
                "{label} exp[{i},{j}]: {got:e} != {want:e}"
            );
        }
    }
}

#[test]
fn expm_matches_wolfram() {
    let fixture = parse_matrix_functions();
    check_expm("expm_nonsym_3x3", &fixture.expm_nonsym_3x3);
    check_expm("expm_skew_2x2", &fixture.expm_skew_2x2);
}

#[test]
fn wide_svd_matches_wolfram_singular_values() {
    let fixture = parse_matrix_functions();
    let case = &fixture.svd_wide_2x4;
    let matrix = dense_real(&case.a);
    let (m, n) = (matrix.nrows(), matrix.ncols());
    assert_eq!((m, n), (2, 4));
    let svd = dense_svd(&matrix).expect("dense_svd failed");
    let expected: Vec<f64> = case
        .singular_values
        .iter()
        .map(|value| parse(value))
        .collect();
    assert_eq!(svd.singular_values.len(), expected.len());
    for (index, (got, want)) in svd.singular_values.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).abs() <= 1e-12 * want.abs().max(1.0),
            "sigma[{index}]: {got:e} != {want:e}"
        );
    }
    assert!(
        svd.singular_values
            .windows(2)
            .all(|pair| pair[0] >= pair[1])
    );
    // Wide reconstruction A = U Σ V^T through the swapped factors.
    assert_eq!(svd.u.shape(), (m, m));
    assert_eq!(svd.v.shape(), (n, m));
    for i in 0..m {
        for j in 0..n {
            let mut sum = 0.0;
            for k in 0..expected.len() {
                sum += svd.u[[i, k]] * svd.singular_values[k] * svd.v[[j, k]];
            }
            assert!(
                (sum - matrix[[i, j]]).abs() <= 1e-12,
                "reconstruction[{i},{j}]: {sum:e} != {:e}",
                matrix[[i, j]]
            );
        }
    }
}

#[test]
fn lu_conj_transpose_matches_plain_on_real() {
    // On real matrices A^H = A^T: the two entry points must agree exactly.
    let fixture = parse_fixture();
    let matrix = dense_real(&fixture.nonsym_3x3.a);
    let b: Vec<f64> = fixture
        .nonsym_3x3
        .b
        .iter()
        .map(|value| parse(value))
        .collect();
    let via_transpose = lu_solve_transpose(&matrix, &b).expect("transpose solve failed");
    let via_hermitian = lu_solve_conj_transpose(&matrix, &b).expect("conj-transpose solve failed");
    assert_eq!(via_transpose, via_hermitian);
}
